//   Typhon runtime: the statistics module, digit for digit like CPython's. Like CPython, mean, variance and friends sum
//   the data exactly (as fractions; every float is a dyadic rational) and round once at the end, stdev takes a correctly
//   rounded square root of the exact fraction, fmean and geometric_mean use fsum, and ints stay ints where CPython keeps
//   them (mean([1, 2, 3]) is 2, mean([1, 2]) is 1.5: such results are late-bound values).
// </auto-generated>
#nullable enable
#pragma warning disable

namespace Typhon.Runtime
{
    using System;
    using System.Collections;
    using System.Collections.Generic;
    using System.Globalization;
    using System.Linq;
    using System.Numerics;

    /// <summary>An exact fraction N/D in lowest terms with D &gt; 0 (statistics' internal arithmetic).</summary>
    internal readonly struct ExactRatio
    {
        public readonly BigInteger N, D;

        public ExactRatio(BigInteger n, BigInteger d)
        {
            if (d.IsZero) throw new DivideByZeroException("division by zero");
            if (d.Sign < 0) { n = -n; d = -d; }
            var g = BigInteger.GreatestCommonDivisor(n, d);
            if (!g.IsOne && !g.IsZero) { n /= g; d /= g; }
            if (n.IsZero) d = BigInteger.One;
            N = n; D = d;
        }

        public static ExactRatio Of(long x) => new ExactRatio(x, BigInteger.One);

        /// <summary>The exact value of a finite double (x.as_integer_ratio()).</summary>
        public static ExactRatio Of(double x)
        {
            var (m, e) = ExactMath.Decompose(x);
            return Scaled(m, e);
        }

        /// <summary>m·2^e.</summary>
        public static ExactRatio Scaled(BigInteger m, int e) => e >= 0 ? new ExactRatio(m << e, BigInteger.One) : new ExactRatio(m, BigInteger.One << -e);

        public bool IsInteger => D.IsOne;
        public int Sign => N.Sign;
        public double ToDouble() => ExactMath.Divide(N, D);

        public static ExactRatio operator +(ExactRatio a, ExactRatio b) => new ExactRatio(a.N * b.D + b.N * a.D, a.D * b.D);
        public static ExactRatio operator -(ExactRatio a, ExactRatio b) => new ExactRatio(a.N * b.D - b.N * a.D, a.D * b.D);
        public static ExactRatio operator *(ExactRatio a, ExactRatio b) => new ExactRatio(a.N * b.N, a.D * b.D);
        public static ExactRatio operator /(ExactRatio a, ExactRatio b) => new ExactRatio(a.N * b.D, a.D * b.N);
    }

    /// <summary>
    /// An exact sum of ints and floats, kept as A·2^E (every float is an integer times a power of two), with the count and
    /// whether a float was seen (CPython's _sum: the result type T). Infinities and NaNs are summed apart, as floats.
    /// </summary>
    internal sealed class ExactSum
    {
        BigInteger _a;
        int _e;
        public long Count;
        public bool AnyFloat;
        public double Special;
        public bool HasSpecial;

        public void AddScaled(BigInteger m, int e)
        {
            if (m.IsZero) return;
            if (_a.IsZero) { _a = m; _e = e; return; }
            if (e >= _e) _a += m << (e - _e);
            else { _a = (_a << (_e - e)) + m; _e = e; }
        }

        public void Add(long x) { Count++; AddScaled(x, 0); }
        public void Add(BigInteger x) { Count++; AddScaled(x, 0); }
        public void Add(double x)
        {
            Count++; AnyFloat = true;
            if (!double.IsFinite(x)) { Special = HasSpecial ? Special + x : x; HasSpecial = true; return; }
            var (m, e) = ExactMath.Decompose(x);
            AddScaled(m, e);
        }
        public void AddSquare(BigInteger x) => AddScaled(x * x, 0);
        public void AddSquare(double x)
        {
            if (!double.IsFinite(x)) return;
            var (m, e) = ExactMath.Decompose(x);
            AddScaled(m * m, 2 * e);
        }

        public ExactRatio Value => ExactRatio.Scaled(_a, _e);
    }

    /// <summary>Correctly rounded conversions between exact values and floats, fsum, integer square roots.</summary>
    internal static class ExactMath
    {
        /// <summary>A finite double as m·2^e with an integer m (odd unless zero).</summary>
        public static (BigInteger m, int e) Decompose(double x)
        {
            long bits = BitConverter.DoubleToInt64Bits(x);
            bool neg = bits < 0;
            int exp = (int)((bits >> 52) & 0x7FF);
            long mant = bits & 0xFFFFFFFFFFFFFL;
            if (exp == 0) exp = 1; else mant |= 1L << 52;
            exp -= 1075;
            if (mant == 0) return (BigInteger.Zero, 0);
            while ((mant & 1) == 0) { mant >>= 1; exp++; }
            return (neg ? -mant : mant, exp);
        }

        public static int BitLength(BigInteger n) => n.IsZero ? 0 : (int)BigInteger.Abs(n).GetBitLength();

        /// <summary>n / d as a float, correctly rounded (round half to even), like Python's int / int.</summary>
        public static double Divide(BigInteger n, BigInteger d)
        {
            if (d.IsZero) throw new DivideByZeroException("division by zero");
            if (n.IsZero) return d.Sign < 0 ? -0.0 : 0.0;
            bool neg = (n.Sign < 0) != (d.Sign < 0);
            n = BigInteger.Abs(n); d = BigInteger.Abs(d);
            int e = BitLength(n) - BitLength(d);          // n/d in (2^(e-1), 2^(e+1))
            int s = Math.Max(e - 54, -1076);               // q = n/d·2^-s has 54..55 bits (fewer for subnormals)
            BigInteger num = s < 0 ? n << -s : n, den = s > 0 ? d << s : d;
            var q = BigInteger.DivRem(num, den, out var rem);
            int qb = BitLength(q);
            int sFinal = Math.Max(s + qb - 53, -1074);
            int drop = sFinal - s;
            BigInteger mant = q >> drop, low = q & ((BigInteger.One << drop) - 1), half = BigInteger.One << (drop - 1);
            if (low > half || low == half && (!rem.IsZero || !mant.IsEven)) mant += 1;
            if (sFinal + BitLength(mant) > 1024) throw new OverflowException("integer division result too large for a float");
            double r = Math.ScaleB((double)(long)mant, sFinal);
            return neg ? -r : r;
        }

        /// <summary>math.fsum: the correctly rounded sum (Shewchuk's partials, CPython's algorithm and special cases).</summary>
        public static double FSum(IEnumerable<double> xs)
        {
            var p = new List<double>();
            double specialSum = 0.0, infSum = 0.0;
            foreach (double item in xs)
            {
                double x = item, xsave = x;
                int i = 0;
                for (int j = 0; j < p.Count; j++)
                {
                    double y = p[j];
                    if (Math.Abs(x) < Math.Abs(y)) { double t = x; x = y; y = t; }
                    double hi = x + y, yr = hi - x, lo = y - yr;
                    if (lo != 0.0) p[i++] = lo;
                    x = hi;
                }
                p.RemoveRange(i, p.Count - i);
                if (x != 0.0)
                {
                    if (!double.IsFinite(x))
                    {
                        if (double.IsFinite(xsave)) throw new OverflowException("intermediate overflow in fsum");
                        if (double.IsInfinity(xsave)) infSum += xsave;
                        specialSum += xsave;
                        p.Clear();
                    }
                    else p.Add(x);
                }
            }
            if (specialSum != 0.0)
            {
                if (double.IsNaN(infSum)) throw new ArgumentException("-inf + inf in fsum");
                return specialSum;
            }
            double sum = 0.0;
            int n = p.Count;
            if (n > 0)
            {
                double lo = 0.0;
                sum = p[--n];
                while (n > 0)
                {
                    double x = sum, y = p[--n];
                    sum = x + y;
                    double yr = sum - x;
                    lo = y - yr;
                    if (lo != 0.0) break;
                }
                if (n > 0 && (lo < 0.0 && p[n - 1] < 0.0 || lo > 0.0 && p[n - 1] > 0.0))
                {
                    double y = lo * 2.0, x = sum + y, yr = x - sum;
                    if (y == yr) sum = x;
                }
            }
            return sum;
        }

        /// <summary>math.isqrt for big integers: the floor of the square root.</summary>
        public static BigInteger ISqrt(BigInteger n)
        {
            if (n.Sign < 0) throw new ArgumentException("isqrt() argument must be nonnegative");
            if (n < 2) return n;
            var x = BigInteger.One << ((BitLength(n) + 1) / 2);
            while (true)
            {
                var y = (x + n / x) >> 1;
                if (y >= x) return x;
                x = y;
            }
        }

        public static BigInteger FloorDiv(BigInteger a, BigInteger b)
        {
            var q = BigInteger.DivRem(a, b, out var r);
            return !r.IsZero && (r.Sign < 0) != (b.Sign < 0) ? q - 1 : q;
        }

        /// <summary>The square root of n/m rounded to an integer with round-to-odd (statistics._integer_sqrt_of_frac_rto).</summary>
        static BigInteger ISqrtOfFracRto(BigInteger n, BigInteger m)
        {
            var a = ISqrt(FloorDiv(n, m));
            return a * a * m != n ? a | BigInteger.One : a;
        }

        /// <summary>sqrt(n/m) as a correctly rounded float (statistics._float_sqrt_of_frac).</summary>
        public static double SqrtOfFrac(BigInteger n, BigInteger m)
        {
            const int width = 2 * 53 + 3;
            int q = (int)FloorDiv(BitLength(n) - BitLength(m) - width, 2);
            if (q >= 0) return Divide(ISqrtOfFracRto(n, m << (2 * q)) << q, BigInteger.One);
            return Divide(ISqrtOfFracRto(n << (-2 * q), m), BigInteger.One << -q);
        }

        /// <summary>A number of a list Typhon passed as a non-generic sequence (weights): exact, or null for inf/nan.</summary>
        public static ExactRatio? Exact(object? x) => x switch
        {
            long l => ExactRatio.Of(l),
            int i => ExactRatio.Of(i),
            bool b => ExactRatio.Of(b ? 1 : 0),
            double d when double.IsFinite(d) => ExactRatio.Of(d),
            double => null,
            BigInteger big => new ExactRatio(big, BigInteger.One),
            _ => ExactRatio.Of(Convert.ToDouble(x, CultureInfo.InvariantCulture)),
        };

        public static double ToDouble(object? x) => x switch
        {
            long l => l,
            double d => d,
            bool b => b ? 1.0 : 0.0,
            BigInteger big => (double)big,
            _ => Convert.ToDouble(x, CultureInfo.InvariantCulture),
        };

        /// <summary>An int (long or BigInteger) as a BigInteger.</summary>
        public static bool IsInt(object? x, out BigInteger v)
        {
            switch (x)
            {
                case long l: v = l; return true;
                case BigInteger b: v = b; return true;
                case int i: v = i; return true;
                default: v = default; return false;
            }
        }

        /// <summary>math.sumprod: the sum of products, computed exactly and rounded once (ints only: exact).</summary>
        public static double SumProd(IList<object?> a, IList<object?> b)
        {
            var total = ExactRatio.Of(0L);
            double special = 0;
            bool anySpecial = false;
            for (int i = 0; i < a.Count; i++)
            {
                var x = Exact(a[i]);
                var y = Exact(b[i]);
                if (x == null || y == null) { special += ToDouble(a[i]) * ToDouble(b[i]); anySpecial = true; continue; }
                total += x.Value * y.Value;
            }
            return anySpecial ? special : total.ToDouble();
        }
    }
}

namespace Typhon.Stdlib
{
    using System;
    using System.Collections;
    using System.Collections.Generic;
    using System.Linq;
    using System.Numerics;
    using Typhon.Runtime;

    /// <summary>
    /// The statistics module. Overloads for ints (IEnumerable&lt;long&gt;, or BigInteger in big-int mode) and floats
    /// (IEnumerable&lt;double&gt;): where CPython's result type depends on the values (mean, median, variance of ints;
    /// harmonic_mean), the result is late-bound.
    /// </summary>
    internal static class statistics
    {
        /// <summary>statistics.StatisticsError: a ValueError.</summary>
        internal sealed class StatisticsError : ArgumentException
        {
            public StatisticsError(string message) : base(message) { }
        }

        /// <summary>CPython's _convert(value, T) for T = int: an int when the fraction is whole (a BigInteger in big-int mode or when it does not fit), else a float.</summary>
        static object IntOrFloat(ExactRatio r, bool big) =>
            !r.IsInteger ? r.ToDouble() : !big && r.N >= long.MinValue && r.N <= long.MaxValue ? (object)(long)r.N : r.N;

        static List<T> Sorted<T>(IEnumerable<T> data) => Builtins.sorted(data);
        static IEnumerable<BigInteger> Big(IEnumerable<long> data) => data.Select(x => (BigInteger)x);

        // ── averages ──

        public static dynamic mean(IEnumerable<long> data) => MeanInt(Big(data), false);
        public static dynamic mean(IEnumerable<BigInteger> data) => MeanInt(data, true);

        static object MeanInt(IEnumerable<BigInteger> data, bool big)
        {
            var s = new ExactSum();
            foreach (var x in data) s.Add(x);
            if (s.Count < 1) throw new StatisticsError("mean requires at least one data point");
            return IntOrFloat(s.Value / ExactRatio.Of(s.Count), big);
        }

        public static double mean(IEnumerable<double> data)
        {
            var s = new ExactSum();
            foreach (var x in data) s.Add(x);
            if (s.Count < 1) throw new StatisticsError("mean requires at least one data point");
            if (s.HasSpecial) return s.Special / s.Count;
            return (s.Value / ExactRatio.Of(s.Count)).ToDouble();
        }

        public static double fmean(IEnumerable<long> data, IEnumerable? weights = null) =>
            weights == null ? FMean(data.Select(x => (double)x)) : WeightedFMean(data.Cast<object?>().ToList(), weights);

        public static double fmean(IEnumerable<BigInteger> data, IEnumerable? weights = null) =>
            weights == null ? FMean(data.Select(x => (double)x)) : WeightedFMean(data.Cast<object?>().ToList(), weights);

        public static double fmean(IEnumerable<double> data, IEnumerable? weights = null) =>
            weights == null ? FMean(data) : WeightedFMean(data.Cast<object?>().ToList(), weights);

        static double FMean(IEnumerable<double> data)
        {
            long n = 0;
            double total = ExactMath.FSum(data.Select(x => { n++; return x; }));
            if (n == 0) throw new StatisticsError("fmean requires at least one data point");
            return total / n;
        }

        static double WeightedFMean(List<object?> data, IEnumerable weights)
        {
            var w = weights.Cast<object?>().ToList();
            if (w.Count != data.Count) throw new StatisticsError("data and weights must be the same length");
            double num = ExactMath.SumProd(data, w);
            double den = ExactMath.FSum(w.Select(ExactMath.ToDouble));
            if (den == 0) throw new StatisticsError("sum of weights must be non-zero");
            return num / den;
        }

        public static double geometric_mean(IEnumerable<long> data) => GeometricMean(data.Select(x => (object)x));
        public static double geometric_mean(IEnumerable<BigInteger> data) => GeometricMean(data.Select(x => (object)x));
        public static double geometric_mean(IEnumerable<double> data) => GeometricMean(data.Select(x => (object)x));

        static double GeometricMean(IEnumerable<object> data)
        {
            long n = 0;
            bool foundZero = false;
            IEnumerable<double> Positive()
            {
                foreach (var item in data)
                {
                    n++;
                    double x = ExactMath.ToDouble(item);
                    if (x > 0.0 || double.IsNaN(x)) yield return x;
                    else if (x == 0.0) foundZero = true;
                    else throw new StatisticsError($"('No negative inputs allowed', {Builtins.repr(item)})");
                }
            }
            double total = ExactMath.FSum(Positive().Select(x => Math.Log(x)));
            if (n == 0) throw new StatisticsError("Must have a non-empty dataset");
            if (double.IsNaN(total)) return double.NaN;
            if (foundZero) return double.IsPositiveInfinity(total) ? double.NaN : 0.0;
            return Math.Exp(total / n);
        }

        const string HarmonicNegative = "harmonic mean does not support negative values";

        public static dynamic harmonic_mean(IEnumerable<long> data, IEnumerable? weights = null) => HarmonicMean(data.Select(x => (object)x).ToList(), weights, false);
        public static dynamic harmonic_mean(IEnumerable<BigInteger> data, IEnumerable? weights = null) => HarmonicMean(data.Select(x => (object)x).ToList(), weights, true);
        public static dynamic harmonic_mean(IEnumerable<double> data, IEnumerable? weights = null) => HarmonicMean(data.Select(x => (object)x).ToList(), weights, false);

        static object HarmonicMean(List<object> data, IEnumerable? weights, bool big)
        {
            int n = data.Count;
            object zero = big ? (object)BigInteger.Zero : 0L;
            if (n < 1) throw new StatisticsError("harmonic_mean requires at least one data point");
            if (n == 1 && weights == null)
            {
                if (ExactMath.ToDouble(data[0]) < 0) throw new StatisticsError(HarmonicNegative);
                return data[0];
            }
            List<object?> ws;
            ExactRatio sumWeights;
            if (weights == null)
            {
                ws = Enumerable.Repeat((object?)1L, n).ToList();
                sumWeights = ExactRatio.Of(n);
            }
            else
            {
                ws = weights.Cast<object?>().ToList();
                if (ws.Count != n) throw new StatisticsError("Number of weights does not match data size");
                sumWeights = ExactRatio.Of(0L);
                foreach (var w in ws)
                {
                    if (ExactMath.ToDouble(w) < 0) throw new StatisticsError(HarmonicNegative);
                    sumWeights += ExactMath.Exact(w) ?? ExactRatio.Of(0L);
                }
            }
            var total = new ExactSum();
            for (int i = 0; i < n; i++)
            {
                object? w = ws[i], x = data[i];
                if (ExactMath.ToDouble(x) < 0) throw new StatisticsError(HarmonicNegative);
                if (ExactMath.ToDouble(w) == 0) { total.Add(0L); continue; }
                double q;
                if (ExactMath.IsInt(w, out var bw) && ExactMath.IsInt(x, out var bx))
                {
                    if (bx.IsZero) return zero; // ZeroDivisionError: CPython returns 0
                    q = ExactMath.Divide(bw, bx);
                }
                else
                {
                    double dx = ExactMath.ToDouble(x);
                    if (dx == 0) return zero;
                    q = ExactMath.ToDouble(w) / dx;
                }
                total.Add(q);
            }
            if (total.HasSpecial) return sumWeights.ToDouble() / total.Special;
            var t = total.Value;
            if (t.Sign <= 0) throw new StatisticsError("Weighted sum must be positive");
            var r = sumWeights / t;
            return total.AnyFloat ? r.ToDouble() : IntOrFloat(r, big);
        }

        // ── medians and modes ──

        public static dynamic median(IEnumerable<long> data) => MedianInt(Big(data), false);
        public static dynamic median(IEnumerable<BigInteger> data) => MedianInt(data, true);

        static object MedianInt(IEnumerable<BigInteger> data, bool big)
        {
            var d = Sorted(data);
            int n = d.Count;
            if (n == 0) throw new StatisticsError("no median for empty data");
            if (n % 2 == 1) return IntOrFloat(new ExactRatio(d[n / 2], BigInteger.One), big);
            return ExactMath.Divide(d[n / 2 - 1] + d[n / 2], 2);
        }

        public static double median(IEnumerable<double> data)
        {
            var d = Sorted(data);
            int n = d.Count;
            if (n == 0) throw new StatisticsError("no median for empty data");
            if (n % 2 == 1) return d[n / 2];
            return (d[n / 2 - 1] + d[n / 2]) / 2;
        }

        public static T median_low<T>(IEnumerable<T> data)
        {
            var d = Sorted(data);
            int n = d.Count;
            if (n == 0) throw new StatisticsError("no median for empty data");
            return n % 2 == 1 ? d[n / 2] : d[n / 2 - 1];
        }

        public static T median_high<T>(IEnumerable<T> data)
        {
            var d = Sorted(data);
            if (d.Count == 0) throw new StatisticsError("no median for empty data");
            return d[d.Count / 2];
        }

        public static double median_grouped(IEnumerable<long> data, double interval = 1.0) => MedianGrouped(Sorted(data).Select(x => (double)x).ToList(), interval);
        public static double median_grouped(IEnumerable<BigInteger> data, double interval = 1.0) => MedianGrouped(Sorted(data).Select(x => (double)x).ToList(), interval);
        public static double median_grouped(IEnumerable<double> data, double interval = 1.0) => MedianGrouped(Sorted(data), interval);

        static double MedianGrouped(List<double> d, double interval)
        {
            int n = d.Count;
            if (n == 0) throw new StatisticsError("no median for empty data");
            double x = d[n / 2];
            int i = 0;
            while (i < n && d[i] < x) i++;
            int j = i;
            while (j < n && d[j] <= x) j++;
            double L = x - interval / 2.0;
            long cf = i, f = j - i;
            return L + interval * ((double)n / 2 - cf) / f;
        }

        static List<(T Value, long Count)> Counts<T>(IEnumerable<T> data)
        {
            var index = new Dictionary<T, int>();
            var counts = new List<(T, long)>();
            int nullAt = -1;
            foreach (var x in data)
            {
                if (x is null)
                {
                    if (nullAt < 0) { nullAt = counts.Count; counts.Add((x, 1)); }
                    else counts[nullAt] = (x, counts[nullAt].Item2 + 1);
                    continue;
                }
                if (index.TryGetValue(x, out int k)) counts[k] = (x, counts[k].Item2 + 1);
                else { index[x] = counts.Count; counts.Add((x, 1)); }
            }
            return counts;
        }

        /// <summary>mode: the most common value (the first one seen among equally common values).</summary>
        public static T mode<T>(IEnumerable<T> data)
        {
            var counts = Counts(data);
            if (counts.Count == 0) throw new StatisticsError("no mode for empty data");
            var best = counts[0];
            foreach (var c in counts) if (c.Count > best.Count) best = c;
            return best.Value;
        }

        public static string mode(string data) => mode(data.Select(c => c.ToString()));

        /// <summary>multimode: the most common values, in the order first seen.</summary>
        public static List<T> multimode<T>(IEnumerable<T> data)
        {
            var counts = Counts(data);
            if (counts.Count == 0) return new List<T>();
            long max = counts.Max(c => c.Count);
            return counts.Where(c => c.Count == max).Select(c => c.Value).ToList();
        }

        public static List<string> multimode(string data) => multimode(data.Select(c => c.ToString()));

        // ── spread ──

        /// <summary>CPython's _ss: the exact sum of squared deviations, whether a float was involved, the count (and an inf/nan sum).</summary>
        static (ExactRatio Ss, bool Float, long Count, double? Special) SumOfSquares(IEnumerable<BigInteger> data, object? c)
        {
            if (c is double dc) return SumOfSquares(data.Select(x => (double)x), dc);
            if (c != null)
            {
                if (!ExactMath.IsInt(c, out var bc)) bc = new BigInteger(Convert.ToInt64(c));
                var s = new ExactSum();
                foreach (var x in data) { var d = x - bc; s.AddScaled(d * d, 0); s.Count++; }
                return (s.Value, false, s.Count, null);
            }
            var sx = new ExactSum();
            var sxx = new ExactSum();
            foreach (var x in data) { sx.Add(x); sxx.AddSquare(x); }
            return (Deviations(sx, sxx), false, sx.Count, null);
        }

        static (ExactRatio Ss, bool Float, long Count, double? Special) SumOfSquares(IEnumerable<double> data, double? c)
        {
            if (c != null)
            {
                var s = new ExactSum();
                foreach (var x in data) { double d = x - c.Value; s.Add(d * d); }
                return (s.HasSpecial ? default : s.Value, true, s.Count, s.HasSpecial ? s.Special : null);
            }
            var sx = new ExactSum();
            var sxx = new ExactSum();
            foreach (var x in data) { sx.Add(x); sxx.AddSquare(x); }
            if (sx.HasSpecial) return (default, true, sx.Count, sx.Special);
            return (Deviations(sx, sxx), true, sx.Count, null);
        }

        static ExactRatio Deviations(ExactSum sx, ExactSum sxx)
        {
            if (sx.Count == 0) return ExactRatio.Of(0L);
            var n = ExactRatio.Of(sx.Count);
            var s = sx.Value;
            return (n * sxx.Value - s * s) / n;
        }

        static object VarianceInt(IEnumerable<BigInteger> data, object? xbar, bool big, bool population)
        {
            var (ss, isFloat, n, special) = SumOfSquares(data, xbar);
            if (population ? n < 1 : n < 2)
                throw new StatisticsError(population ? "pvariance requires at least one data point" : "variance requires at least two data points");
            long divisor = population ? n : n - 1;
            if (special != null) return special.Value / divisor;
            var r = ss / ExactRatio.Of(divisor);
            return isFloat ? r.ToDouble() : IntOrFloat(r, big);
        }

        static double VarianceFloat(IEnumerable<double> data, double? xbar, bool population)
        {
            var (ss, _, n, special) = SumOfSquares(data, xbar);
            if (population ? n < 1 : n < 2)
                throw new StatisticsError(population ? "pvariance requires at least one data point" : "variance requires at least two data points");
            long divisor = population ? n : n - 1;
            if (special != null) return special.Value / divisor;
            return (ss / ExactRatio.Of(divisor)).ToDouble();
        }

        public static dynamic variance(IEnumerable<long> data, object? xbar = null) => VarianceInt(Big(data), xbar, false, false);
        public static dynamic variance(IEnumerable<BigInteger> data, object? xbar = null) => VarianceInt(data, xbar, true, false);
        public static double variance(IEnumerable<double> data, double? xbar = null) => VarianceFloat(data, xbar, false);
        public static dynamic pvariance(IEnumerable<long> data, object? mu = null) => VarianceInt(Big(data), mu, false, true);
        public static dynamic pvariance(IEnumerable<BigInteger> data, object? mu = null) => VarianceInt(data, mu, true, true);
        public static double pvariance(IEnumerable<double> data, double? mu = null) => VarianceFloat(data, mu, true);

        static double Root((ExactRatio Ss, bool Float, long Count, double? Special) s, bool population)
        {
            if (population ? s.Count < 1 : s.Count < 2)
                throw new StatisticsError(population ? "pstdev requires at least one data point" : "stdev requires at least two data points");
            if (s.Special != null) throw new ArgumentException("inf or nan encountered in data");
            var mss = s.Ss / ExactRatio.Of(population ? s.Count : s.Count - 1);
            return ExactMath.SqrtOfFrac(mss.N, mss.D);
        }

        public static double stdev(IEnumerable<long> data, object? xbar = null) => Root(SumOfSquares(Big(data), xbar), false);
        public static double stdev(IEnumerable<BigInteger> data, object? xbar = null) => Root(SumOfSquares(data, xbar), false);
        public static double stdev(IEnumerable<double> data, double? xbar = null) => Root(SumOfSquares(data, xbar), false);
        public static double pstdev(IEnumerable<long> data, object? mu = null) => Root(SumOfSquares(Big(data), mu), true);
        public static double pstdev(IEnumerable<BigInteger> data, object? mu = null) => Root(SumOfSquares(data, mu), true);
        public static double pstdev(IEnumerable<double> data, double? mu = null) => Root(SumOfSquares(data, mu), true);

        // ── quantiles ──

        static void CheckQuantiles(long n) { if (n < 1) throw new StatisticsError("n must be at least 1"); }

        public static List<double> quantiles(IEnumerable<long> data, long n = 4, string method = "exclusive") => QuantilesInt(Big(data), n, method);
        public static List<double> quantiles(IEnumerable<BigInteger> data, long n = 4, string method = "exclusive") => QuantilesInt(data, n, method);

        static List<double> QuantilesInt(IEnumerable<BigInteger> data, long n, string method)
        {
            CheckQuantiles(n);
            var d = Sorted(data);
            return Quantiles(d.Count, n, method, i => d[i], x => (double)x, (a, wa, b, wb) => ExactMath.Divide(a * wa + b * wb, n));
        }

        public static List<double> quantiles(IEnumerable<double> data, long n = 4, string method = "exclusive")
        {
            CheckQuantiles(n);
            var d = Sorted(data);
            return Quantiles(d.Count, n, method, i => d[i], x => x, (a, wa, b, wb) => (a * wa + b * wb) / n);
        }

        static List<double> Quantiles<T>(int ld, long n, string method, Func<int, T> at, Func<T, double> toDouble, Func<T, long, T, long, double> interpolate)
        {
            var result = new List<double>();
            if (ld < 2)
            {
                if (ld == 1) { for (long i = 1; i < n; i++) result.Add(toDouble(at(0))); return result; }
                throw new StatisticsError("must have at least one data point");
            }
            if (method == "inclusive")
            {
                long m = ld - 1;
                for (long i = 1; i < n; i++)
                {
                    long j = i * m / n, delta = i * m % n;
                    result.Add(interpolate(at((int)j), n - delta, at((int)j + 1), delta));
                }
                return result;
            }
            if (method == "exclusive")
            {
                long m = ld + 1;
                for (long i = 1; i < n; i++)
                {
                    long j = i * m / n;
                    j = j < 1 ? 1 : j > ld - 1 ? ld - 1 : j;
                    long delta = i * m - j * n;
                    result.Add(interpolate(at((int)j - 1), n - delta, at((int)j), delta));
                }
                return result;
            }
            throw new ArgumentException($"Unknown method: {Builtins.repr(method)}");
        }
    }
}
